"""Click CLI wiring for the tracker."""
from __future__ import annotations

import click

from tracker.commands import (
    blocked,
    export_csv,
    import_csv,
    issue_add,
    issue_block,
    issue_close,
    issue_list,
    issue_search,
    issue_set,
    issue_show,
    issue_unblock,
    project_add,
    project_list,
    ready,
    report_assignee,
    report_priority,
    report_status,
)


def _print_result(exit_code: int, lines: list[str]) -> None:
    """Print output lines and exit with the given code."""
    for line in lines:
        click.echo(line)
    if exit_code != 0:
        raise SystemExit(exit_code)


class DbGroup(click.Group):
    """Custom group that stores --db path on the context."""

    def __call__(self, *args, **kwargs):
        return super().__call__(*args, **kwargs)

    def get_command(self, ctx: click.Context, cmd_name: str):
        return super().get_command(ctx, cmd_name)

    def invoke(self, ctx: click.Context):
        return super().invoke(ctx)


@click.group(invoke_without_command=True)
@click.option("--db", "-d", default="tracker.db", help="Path to the SQLite database.")
@click.pass_context
def cli(ctx: click.Context, db: str) -> None:
    """A lightweight issue tracker with dependencies."""
    ctx.ensure_object(dict)
    ctx.obj["db"] = db


# ── project ───────────────────────────────────────────────

@cli.group()
def project() -> None:
    """Manage projects."""
    pass


@project.command("add")
@click.argument("name")
@click.pass_context
def project_add_cmd(ctx: click.Context, name: str) -> None:
    _print_result(*project_add(ctx.obj["db"], name))


@project.command("list")
@click.pass_context
def project_list_cmd(ctx: click.Context) -> None:
    _print_result(*project_list(ctx.obj["db"]))


# ── issue ─────────────────────────────────────────────────

@cli.group()
def issue() -> None:
    """Manage issues."""
    pass


@issue.command("add")
@click.argument("project")
@click.argument("title")
@click.option("--desc", "-D", default="", help="Description.")
@click.option("--priority", "-p", default="medium", help="Priority.")
@click.option("--assignee", "-a", default="", help="Assignee.")
@click.option("--label", "-l", multiple=True, help="Label (repeatable).")
@click.pass_context
def issue_add_cmd(
    ctx: click.Context,
    project: str,
    title: str,
    desc: str,
    priority: str,
    assignee: str,
    label: tuple[str, ...],
) -> None:
    _print_result(
        *issue_add(ctx.obj["db"], project, title, desc=desc, priority=priority, assignee=assignee, labels=list(label))
    )


@issue.command("show")
@click.argument("issue_id", type=int)
@click.pass_context
def issue_show_cmd(ctx: click.Context, issue_id: int) -> None:
    _print_result(*issue_show(ctx.obj["db"], issue_id))


@issue.command("set")
@click.argument("issue_id", type=int)
@click.option("--status", "-s", default=None, help="New status.")
@click.option("--priority", "-p", default=None, help="New priority.")
@click.option("--assignee", "-a", default=None, help="New assignee.")
@click.option("--label", "-l", default=None, help="Add a label.")
@click.option("--unlabel", "-u", default=None, help="Remove a label.")
@click.pass_context
def issue_set_cmd(
    ctx: click.Context,
    issue_id: int,
    status: str | None,
    priority: str | None,
    assignee: str | None,
    label: str | None,
    unlabel: str | None,
) -> None:
    _print_result(*issue_set(ctx.obj["db"], issue_id, status=status, priority=priority, assignee=assignee, label=label, unlabel=unlabel))


@issue.command("close")
@click.argument("issue_id", type=int)
@click.pass_context
def issue_close_cmd(ctx: click.Context, issue_id: int) -> None:
    _print_result(*issue_close(ctx.obj["db"], issue_id))


@issue.command("list")
@click.option("--project", "-P", default=None, help="Filter by project name.")
@click.option("--status", "-s", default=None, help="Filter by status.")
@click.option("--priority", "-p", default=None, help="Filter by priority.")
@click.option("--assignee", "-a", default=None, help="Filter by assignee.")
@click.option("--label", "-l", default=None, help="Filter by label.")
@click.option("--sort", "-o", default="updated", help="Sort by field.")
@click.pass_context
def issue_list_cmd(
    ctx: click.Context,
    project: str | None,
    status: str | None,
    priority: str | None,
    assignee: str | None,
    label: str | None,
    sort: str,
) -> None:
    _print_result(*issue_list(ctx.obj["db"], project=project, status=status, priority=priority, assignee=assignee, label=label, sort=sort))


@issue.command("search")
@click.argument("text")
@click.pass_context
def issue_search_cmd(ctx: click.Context, text: str) -> None:
    _print_result(*issue_search(ctx.obj["db"], text))


@issue.command("block")
@click.argument("issue_id", type=int)
@click.argument("by_ids", nargs=-1, required=True, type=int)
@click.pass_context
def issue_block_cmd(ctx: click.Context, issue_id: int, by_ids: tuple[int, ...]) -> None:
    _print_result(*issue_block(ctx.obj["db"], issue_id, list(by_ids)))


@issue.command("unblock")
@click.argument("issue_id", type=int)
@click.argument("by_ids", nargs=-1, required=True, type=int)
@click.pass_context
def issue_unblock_cmd(ctx: click.Context, issue_id: int, by_ids: tuple[int, ...]) -> None:
    _print_result(*issue_unblock(ctx.obj["db"], issue_id, list(by_ids)))


# ── ready / blocked ───────────────────────────────────────

@cli.command("ready")
@click.pass_context
def ready_cmd(ctx: click.Context) -> None:
    _print_result(*ready(ctx.obj["db"]))


@cli.command("blocked")
@click.pass_context
def blocked_cmd(ctx: click.Context) -> None:
    _print_result(*blocked(ctx.obj["db"]))


