@cli.group()
def report() -> None:
    """Generate reports."""
    pass


@report.command("status")
@click.pass_context
def report_status_cmd(ctx: click.Context) -> None:
    _print_result(*report_status(ctx.obj["db"]))


@report.command("assignee")
@click.pass_context
def report_assignee_cmd(ctx: click.Context) -> None:
    _print_result(*report_assignee(ctx.obj["db"]))


@report.command("priority")
@click.pass_context
def report_priority_cmd(ctx: click.Context) -> None:
    _print_result(*report_priority(ctx.obj["db"]))


# ── export / import ───────────────────────────────────────

@cli.command("export")
@click.argument("csv_path")
@click.pass_context
def export_cmd(ctx: click.Context, csv_path: str) -> None:
    _print_result(*export_csv(ctx.obj["db"], csv_path))


@cli.command("import")
@click.argument("csv_path")
@click.pass_context
def import_cmd(ctx: click.Context, csv_path: str) -> None:
    _print_result(*import_csv(ctx.obj["db"], csv_path))

"""Centralized input validation for the tracker CLI.

All validators return a list of error strings (empty = valid).
"""
from __future__ import annotations

VALID_STATUSES = ("open", "in-progress", "review", "done")
VALID_PRIORITIES = ("low", "medium", "high", "critical")

# Characters that break CSV round-trips (labels are stored as CSV in export).
_FORBIDDEN_LABEL_CHARS = "|"


def validate_non_empty(value: str, field_name: str) -> list[str]:
    """Reject values that are empty or whitespace-only after stripping."""
    if not value.strip():
        return [f"{field_name} must not be empty"]
    return []


def validate_status(status: str) -> list[str]:
    """Strict enum enforcement for issue status."""
    errors = validate_non_empty(status, "status")
    if errors:
        return errors
    s = status.strip().lower()
    if s not in VALID_STATUSES:
        return [f"invalid status {status!r}; must be one of {VALID_STATUSES}"]
    return []


def validate_priority(priority: str) -> list[str]:
    """Strict enum enforcement for issue priority."""
    errors = validate_non_empty(priority, "priority")
    if errors:
        return errors
    p = priority.strip().lower()
    if p not in VALID_PRIORITIES:
        return [f"invalid priority {priority!r}; must be one of {VALID_PRIORITIES}"]
    return []


def validate_label(label: str) -> list[str]:
    """Reject labels that are empty, contain pipe chars (CSV delimiter), or other forbidden characters."""
    errors: list[str] = []
    stripped = label.strip()
    if not stripped:
        errors.append("label must not be empty")
        return errors
    for ch in _FORBIDDEN_LABEL_CHARS:
        if ch in stripped:
            errors.append(f"label must not contain {ch!r} (reserved for CSV)")
    return errors


def validate_labels(labels: list[str]) -> list[str]:
    """Validate every label in a list; returns all errors."""
    errors: list[str] = []
    for label in labels:
        errors.extend(validate_label(label))
    return errors


def validate_assignee(assignee: str | None) -> list[str]:
    """Validate assignee if provided — must be non-empty and free of pipe chars."""
    if assignee is None:
        return []
    stripped = assignee.strip()
    if not stripped:
        return ["assignee must not be empty"]
    for ch in _FORBIDDEN_LABEL_CHARS:
        if ch in stripped:
            return [f"assignee must not contain {ch!r} (reserved for CSV)"]
    return []


def validate_project_name(name: str, existing_names: set[str]) -> list[str]:
    """Reject empty names and duplicates (case-insensitive)."""
    errors: list[str] = []
    stripped = name.strip()
    if not stripped:
        errors.append("project name must not be empty")
        return errors
    if stripped.lower() in existing_names:
        errors.append(f"project name {stripped!r} already exists")
    return errors

from __future__ import annotations

import json
from dataclasses import dataclass, field
from datetime import datetime


def _parse_labels(raw: str | None) -> list[str]:
    if raw is None:
        return []
    try:
        v = json.loads(raw)
        if isinstance(v, list):
            return [str(x) for x in v]
    except (json.JSONDecodeError, TypeError):
        pass
    return []


def _serialize_labels(labels: list[str]) -> str:
    return json.dumps(labels)


def _parse_timestamp(raw: str | None) -> datetime:
    if raw is None:
        return datetime.now()
    # SQLite returns ISO-ish strings; try common formats
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
        try:
            return datetime.strptime(raw, fmt)
        except ValueError:
            continue
    # fallback: try fromisoformat (handles most ISO strings)
    return datetime.fromisoformat(raw.replace("Z", "+00:00").replace("+00:00", ""))


@dataclass
class Project:
    id: int
    name: str


@dataclass
class Issue:
    id: int
    project_id: int
    title: str
    description: str = ""
    status: str = "open"
    priority: str = "medium"
    assignee: str | None = None
    labels: list[str] = field(default_factory=list)
    created_at: datetime | None = None
    updated_at: datetime | None = None


@dataclass
class Dependency:
    issue_id: int
    blocker_id: int
